def wiggle_sort(nums):
    n = len(nums)
    sorted_nums = sorted(nums)
    result = [0] * n

    for i in range(n):
        if i % 2 == 0:
            result[i] = sorted_nums[i // 2]
        else:
            result[i] = sorted_nums[n // 2 + i // 2]

    return result


if __name__ == "__main__":
    print(wiggle_sort([1, 5, 1, 1, 6, 4]))
    print(wiggle_sort([1, 3, 2, 2, 3, 1]))

