public class Main {
    static int[] wiggleSort(int[] nums) {
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int[] result = new int[n];

        int mid = (n + 1) / 2;
        int j = mid - 1, k = n - 1;
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                result[i] = sorted[j--];
            } else {
                result[i] = sorted[k--];
            }
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(wiggleSort(new int[]{1, 5, 1, 1, 6, 4})));
        System.out.println(Arrays.toString(wiggleSort(new int[]{1, 3, 2, 2, 3, 1})));
    }
}

